  test("patrons and backing scenario 2", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    await ui.setSetting(pg_uma, "clerk-limit", "1.50");
    await ui.setSetting(pg_uma, "floor", "0.50");
    await ui.setSetting(pg_uma, "late-pct", "10.00");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33", "from": "2026-03-01"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
    const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.35", "date": "2026-02-25"}));
    expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00", "from": "2026-03-10"})).toBe(true);
    expect(await ui.claimAction(pg_uma, c_cam_0, "void")).toBe(true);
    const c_ben_0 = ui.must(await ui.addClaimTwice(pg_uma, p_ben, {"amount": "10.35", "date": "2026-03-20"}));
    expect(await ui.claimCount(pg_uma, p_ben)).toBe(1);
    expect(await ui.editPerson(pg_uma, p_cam, {"grade": "C"})).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.claimAction(pg_wes, c_ben_0, "open")).toBe(true);
    await ui.refresh(pg_wes);
    expect(await ui.setRate(pg_wes, {"grade": "A", "pct": "7.50", "from": "2026-03-10"})).toBe(true);
    await ui.setToday(pg_wes, "2026-04-08");
    await ui.setToday(pg_wes, "2026-05-16");
    expect(await ui.claimAction(pg_wes, c_ben_0, "void")).toBe(true);
    expect(await ui.hold(pg_wes, p_cam, {})).toBe(true);
    const c_cam_1 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "25.00", "date": "2026-02-10"}));
    await ui.setToday(pg_wes, "2026-06-08");
    await ui.refresh(pg_wes);
    await ui.setSetting(pg_wes, "floor", "3.00");
    expect(await ui.claimAction(pg_wes, c_cam_1, "open")).toBe(true);
    await ui.refresh(pg_uma);
    expect(await ui.claimAction(pg_uma, c_cam_1, "settle")).toBe(false);
    expect(await ui.claimAction(pg_uma, c_cam_1, "settle")).toBe(false);
    expect(await ui.claimAction(pg_uma, c_cam_1, "settle")).toBe(false);
    await ui.refresh(pg_uma);
