# PUT /api/sheets/{sheetId}/people/{personId}/hold — put a person on hold, or take a held person off it
# (a toggle; no body). While held, their OPEN claims count in no live total; their SETTLED ones still
# do. 404 for a person not on the sheet.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.person.LoadPerson
  next: hold
  govern: [ transaction ]
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.person.AuditPersonHeld
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.person.RespondWithEditedPerson
  govern: [ transaction ]
# GET /api/sheets/{sheetId}/people — the sheet's people, in the order they were added.
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class HoldPerson {
    // Toggles the hold: a person not held is put on hold, a held one is released. Person is a record, so
    // the toggled person is published as the response in place of the loaded one.
    public void hold(@Val Person person, People people, Out<PersonResponse> responseOut) {
        Person toggled = new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version(),
                person.retiredFrom(), !person.held());
        people.hold(toggled.id(), toggled.held());
        responseOut.set(PersonResponse.from(toggled));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditPersonHeld {
    public void audit(@Val Person loaded, @Val PersonResponse toggled, ServerHttpConnection connection, Audit audit) {
        audit.record(Audit.line(toggled.held() ? "PERSON_HELD" : "PERSON_RELEASED", loaded.sheetId(),
                Audit.user(connection), "name=" + toggled.name()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            People people, Out<Person> personOut) throws PersonNotFoundException {
        Person person = people.find(sheetId.trim(), personId);
        if (person == null) {
            throw new PersonNotFoundException("No person " + personId + " on this sheet.");
        }
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/** The store of people, kept per sheet. */
@Repository
public class People {

    private static final RowMapper<Person> ROW = (rs, n) -> new Person(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getString("name"), rs.getString("grade"), rs.getLong("version"),
            rs.getObject("retired_from", LocalDate.class), rs.getBoolean("held"));

    private final JdbcTemplate jdbc;

    public People(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's people in the order they were added. */
    public List<Person> list(String sheetId) {
        return jdbc.query("SELECT * FROM person WHERE sheet_id = ? ORDER BY id", ROW, sheetId);
    }

    public Person find(String sheetId, long id) {
        List<Person> found = jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name, ignoring case and surrounding spaces; null when none. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND name_key = LOWER(?)", ROW,
                sheetId, name.trim());
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this name, ignoring case. */
    public boolean nameTaken(String sheetId, String name, long exceptId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name.trim(), exceptId);
        return n != null && n > 0;
    }

    public Person add(String sheetId, PersonRequest request) {
        KeyHolder key = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)", new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, request.name());
            ps.setString(3, request.grade());
            return ps;
        }, key);
        return new Person(key.getKey().longValue(), sheetId, request.name(), request.grade(), 0, null, false);
    }

    /**
     * Store an edited person, whose version is one past the version it was loaded at. False, storing
     * nothing, when the person has been saved since it was loaded.
     */
    public boolean save(Person person) {
        return jdbc.update("UPDATE person SET name = ?, grade = ?, version = ? WHERE id = ? AND version = ?",
                person.name(), person.grade(), person.version(), person.id(), person.version() - 1) == 1;
    }

    /** Retire the person from the date (replacing any date they were retired from before). */
    public void retire(long id, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ?", from, id);
    }

    /** Put the person on hold (true) or take them off it (false). */
    public void hold(long id, boolean held) {
        jdbc.update("UPDATE person SET held = ? WHERE id = ?", held, id);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/**
 * A person on a sheet. {@code grade} is one of A, B or C; {@code version} is raised on every edit.
 * {@code retiredFrom} is the date they are retired from (null when not retired); a person with one set
 * is retired at once, whatever the date. {@code held} is whether they are on hold: while held, their OPEN
 * claims count in no live total.
 */
public record Person(long id, String sheetId, String name, String grade, long version, LocalDate retiredFrom,
        boolean held) {

    public Person with(PersonRequest request) {
        return new Person(id, sheetId, request.name(), request.grade(), version + 1, retiredFrom, held);
    }

    public boolean retired() {
        return retiredFrom != null;
    }
}
